var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Chỉnh sửa cấu hình màn hình cảm ứng KlipperScreen của máy in một cách an toàn, sau đó khởi động lại KlipperScreen để áp dụng. Mỗi lần lưu đều được sao lưu trước.`}},selector:{title:{t:0,b:{t:2,i:[{t:3}],s:`Màn hình cảm ứng`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Chọn giao diện nào chạy trên màn hình của máy in.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Làm mới`}},active:{t:0,b:{t:2,i:[{t:3}],s:`Đang chạy`}},boot:{t:0,b:{t:2,i:[{t:3}],s:`Khi khởi động`}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Chưa cài đặt`}},use:{t:0,b:{t:2,i:[{t:3}],s:`Dùng`}},switching:{t:0,b:{t:2,i:[{t:3}],s:`Đang chuyển…`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Đồng thời đặt làm mặc định khi khởi động`}},installedNotManageable:{t:0,b:{t:2,i:[{t:3}],s:`Đã cài đặt`}},notManageableHint:{t:0,b:{t:2,i:[{t:3}],s:`Đã cài đặt, nhưng không thể chuyển từ đây (không có dịch vụ systemd).`}}},touchPanel:{title:{t:0,b:{t:2,i:[{t:3}],s:`Bảng điều khiển FilaMind`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Chạy các bài kiểm tra và thử nghiệm của FilaMind ngay trên màn hình.`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Trợ giúp`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Về KlipperScreen Studio`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Đóng`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Cách đọc`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Chỉnh sửa nội dung cấu hình bên dưới (hoặc để nguyên).`}},{t:0,b:{t:2,i:[{t:3}],s:`Lưu - tệp hiện tại được sao lưu trước, và lệnh lưu bị từ chối khi máy in đang bận.`}},{t:0,b:{t:2,i:[{t:3}],s:`Khởi động lại KlipperScreen để áp dụng thay đổi trên màn hình vật lý.`}},{t:0,b:{t:2,i:[{t:3}],s:`Các dòng dùng ký tự xuống dòng UNIX (LF), tự động áp dụng khi lưu.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Thuật ngữ`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Định nghĩa nhanh các thuật ngữ KlipperScreen dùng ở đây.`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Tab Config là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Tệp KlipperScreen.conf thô. Chỉnh sửa bất kỳ thiết lập nào bằng tay; lệnh lưu sao lưu tệp trước, bị từ chối khi máy in đang bận, và cảnh báo nếu tệp đã thay đổi trên màn hình kể từ khi bạn tải nó. Hầu hết mọi người dùng tab Settings / Menus / Themes thay vì tab này.`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`Tab Settings là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Các tùy chọn [main] hay dùng nhất dưới dạng biểu mẫu - theme, ngôn ngữ, ngủ màn hình, cỡ chữ và các công tắc. Điền sẵn từ cấu hình đang chạy; chỉ những tùy chọn bạn thay đổi mới được ghi. Khởi động lại để áp dụng.`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`Tab Menus là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Thiết kế các lưới nút của màn hình cảm ứng. Mỗi cây (__main là lưới màn hình chính, __print là màn hình in) liệt kê các nút của nó; thêm, đổi tên, sắp xếp lại và lồng chúng, và đặt mỗi nút để mở một menu con, mở một màn hình tích hợp sẵn, hoặc chạy G-code.`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Tab Themes là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Tạo một theme KlipperScreen: chọn màu cho từng token bảng màu và một độ bo góc, xem bản xem trước trực tiếp, rồi tạo và áp dụng nó lên màn hình. Bản xem trước chỉ mang tính tương đối - màn hình thật được dựng bằng GTK.`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`Tab Kiosk là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Đưa chính FilaMind Flow lên màn hình cảm ứng dưới dạng trình duyệt toàn màn hình - toàn quyền kiểm soát những gì màn hình hiển thị. Đây là một phép hoán đổi có thể đảo ngược với KlipperScreen (mặc định là tạm thời; khởi động lại sẽ khôi phục KlipperScreen). Cần trình cài đặt một lần trên máy chủ máy in.`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Giao diện màn hình cảm ứng chạy trên một màn hình nhỏ gắn vào máy in - tách biệt với bảng điều khiển web này.`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`Theme`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Một diện mạo KlipperScreen - màu sắc, biểu tượng và độ bo góc. Nằm trong thư mục styles/<name> trên máy chủ; chỉ mang tính thẩm mỹ (không thể thay đổi bố cục).`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`Menu (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Các lưới nút mà KlipperScreen hiển thị. __main là màn hình chính, __print là màn hình hiển thị khi đang in, __splashscreen là màn hình khởi động.`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`Panel`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Một màn hình KlipperScreen tích hợp sẵn mà một nút có thể mở (di chuyển, nhiệt độ, đùn, lưới bàn in, …). Nội dung bên trong chúng được KlipperScreen cố định.`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`Khối tự động tạo (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Phần mà KlipperScreen tự ghi ở cuối tệp conf, sau dấu #~#. FilaMind không bao giờ chỉnh sửa nó - chỉ chỉnh các thiết lập của bạn ở phía trên.`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Chạy một trình duyệt toàn màn hình trên màn hình cảm ứng thay cho KlipperScreen, để màn hình hiển thị FilaMind Flow. Hoàn toàn có thể đảo ngược.`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`Đang kiểm tra KlipperScreen…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`Không phát hiện KlipperScreen trên máy in này (không có KlipperScreen.conf, và Moonraker không báo cáo). Hãy cài đặt KlipperScreen để dùng công cụ này.`}},present:{t:0,b:{t:2,i:[{t:3}],s:`Đã phát hiện KlipperScreen`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`Theme`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Ngôn ngữ`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker không thể tự khởi động lại KlipperScreen - hãy khởi động lại thủ công sau khi lưu.`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Đang đọc KlipperScreen.conf…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`Tải lại`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Lưu cấu hình`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Đang lưu…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`Đã lưu (đã sao lưu)`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Thay đổi chưa lưu`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`Bị từ chối khi máy in đang bận - thử lại khi máy rảnh.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf đã thay đổi trên đĩa kể từ khi được tải (có thể đã chỉnh trên màn hình). Hãy tải lại trước khi lưu để không ghi đè thay đổi đó.`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`Config`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Settings`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`Menus`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`Themes`}},kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},fmscreen:{t:0,b:{t:2,i:[{t:3}],s:`Màn hình FilaMind`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Đang tải thiết lập…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Các tùy chọn hiển thị KlipperScreen hay dùng nhất dưới dạng biểu mẫu. Chỉ những tùy chọn bạn thay đổi mới được ghi - mọi thứ khác giữ nguyên giá trị hiện tại. Khởi động lại để áp dụng.`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`Chỉ những thiết lập bạn thay đổi ở đây mới được ghi vào KlipperScreen.conf.`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Lưu thiết lập`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Đã lưu - khởi động lại KlipperScreen để áp dụng.`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`Để trống (mặc định)`}},never:{t:0,b:{t:2,i:[{t:3}],s:`Không bao giờ (luôn bật)`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`Nhỏ`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`Vừa`}},large:{t:0,b:{t:2,i:[{t:3}],s:`Lớn`}},max:{t:0,b:{t:2,i:[{t:3}],s:`Tối đa`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`Theme`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Ngôn ngữ`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`Ngủ màn hình sau`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`Cỡ chữ`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`Đồng hồ 24 giờ`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`Dùng DPMS để tắt màn hình`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`Hiển thị con trỏ chuột`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`Xác nhận trước khi dừng khẩn cấp`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`Hiển thị công suất bộ gia nhiệt %`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`Tự đóng cửa sổ bật lên`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Đang kiểm tra màn hình…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Đưa chính FilaMind Flow lên màn hình cảm ứng dưới dạng trình duyệt toàn màn hình - toàn quyền kiểm soát những gì màn hình hiển thị. Nó hoán đổi với KlipperScreen: khởi động cái này sẽ dừng cái kia.`}},current:{t:0,b:{t:2,i:[{t:3}],s:`Màn hình hiện tại`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk FilaMind`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Không cái nào đang chạy`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk chưa được cài đặt`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`Chạy lệnh này một lần trên máy chủ máy in (cài trình duyệt toàn màn hình + dịch vụ kiosk):`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Đặt làm mặc định khi khởi động (nếu không, phép hoán đổi chỉ là tạm thời - khởi động lại sẽ khôi phục cái kia).`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`Mặc định là tạm thời: khởi động lại sẽ đưa cái kia trở lại. Nếu màn hình bị tối, qua SSH chạy: sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Chuyển sang FilaMind`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`Khôi phục KlipperScreen`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Làm mới`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`Đưa FilaMind lên màn hình?`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`Khôi phục KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Thao tác này dừng một dịch vụ màn hình và khởi động cái kia. Nó không ảnh hưởng đến bản in đang chạy, nhưng màn hình cảm ứng sẽ tối trong vài giây khi chuyển đổi.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Thực hiện`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Hủy`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind đang tiếp quản màn hình - nó sẽ xuất hiện trong vài giây.`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen đang trở lại - màn hình sẽ phục hồi ngay.`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Đang tải menu…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Thiết kế những gì màn hình cảm ứng hiển thị: các nút của mỗi menu, thứ tự của chúng, và mỗi nút làm gì. Lưới màn hình chính là cây __main; màn hình in là __print.`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`Thêm nút`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Chưa có mục nào - hãy thêm một mục.`}},up:{t:0,b:{t:2,i:[{t:3}],s:`Chuyển lên`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Chuyển xuống`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`Thêm mục con`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Xóa`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Tên`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`Biểu tượng`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Hành động`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`Mở một menu con`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`Mở một màn hình`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`Chạy G-code`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`Màn hình`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Hiển thị nếu`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Lưu menu`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`Nút mới`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Đã lưu menu - khởi động lại KlipperScreen để xem chúng.`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Đang tải theme…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`Bảng màu`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`Độ bo góc`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`Xem trước trực tiếp`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`Nút`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`cảnh báo`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`Bản xem trước tương đối - màn hình thật được dựng bằng GTK; có thể có khác biệt nhỏ.`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Tên theme mới`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`Tạo & áp dụng`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`Chỉ tạo`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`Theme đã cài`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Áp dụng`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Xóa theme`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`Tạo tại đây`}},created:{t:0,b:{t:2,i:[{t:3}],s:`Đã tạo theme. Áp dụng nó từ danh sách, rồi khởi động lại.`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Đã đặt theme - khởi động lại KlipperScreen để xem nó.`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`Máy in`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`Khởi động lại KlipperScreen`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Đang khởi động lại…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen đang khởi động lại - màn hình sẽ tải lại ngay.`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Khởi động lại KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Thao tác này khởi động lại dịch vụ màn hình cảm ứng để áp dụng thay đổi của bạn. Nó không ảnh hưởng đến bản in đang chạy, nhưng màn hình sẽ tối trong vài giây.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Khởi động lại`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Hủy`}}}}};export{e as default};